<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\DTO\Request\CreateOrReuseFlashcardRequestDto;use App\Application\Review\Port\TransactionManagerInterface;use App\Domain\Review\Entity\NotebookAnalysisAction;use App\Domain\Review\Enum\FlashcardSource;use App\Domain\Review\Enum\NotebookAnalysisActionType;use App\Domain\Review\Repository\NotebookAnalysisActionRepositoryInterface;
final readonly class ApplyNotebookAnalysisActionsService { public function __construct(private CreateOrReuseFlashcardService $cards,private ApplyNotebookAnalysisSignalsService $signals,private NotebookAnalysisActionRepositoryInterface $actions,private TransactionManagerInterface $transactions){} /** @param list<array{type:string,concept_id:?string,question_id:?string,reason:string,confidence:float,front?:string,back?:string,flashcard_id?:string,user_id?:string}> $items */ public function execute(string $executionId,string $userId,array $items,\DateTimeImmutable $now):void{$this->transactions->transactional(function()use($executionId,$userId,$items,$now):void{foreach($items as $item){$type=NotebookAnalysisActionType::from($item['type']);$cardId=$item['flashcard_id']??null;if($type===NotebookAnalysisActionType::CREATE_OR_REUSE_CARD&&$item['concept_id']!==null){$card=$this->cards->execute(new CreateOrReuseFlashcardRequestDto($item['concept_id'],$item['front']??'', $item['back']??'',FlashcardSource::NOTEBOOK_ANALYSIS),$now);$cardId=$card->id;}if($type===NotebookAnalysisActionType::ADVANCE_CARD&&is_string($cardId))$this->signals->advance($userId,$cardId,$now);if($type===NotebookAnalysisActionType::UPDATE_MASTERY&&$item['concept_id']!==null)$this->signals->updateMastery($userId,$item['concept_id'],$item['confidence'],$now);$this->actions->save(new NotebookAnalysisAction($this->uuid(),$executionId,$item['question_id'],$item['concept_id'],$cardId,$type,$item['reason'],$item['confidence'],[],$now,$now));}});} private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
